  sec.querySelectorAll('[data-pr]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const n=b.dataset.pr;const cur=prOf(n);const nx=PRI[(PRI.findIndex(x=>x[0]===cur)+1)%PRI.length][0];const list=STAFF.map(x=>x.name===n?{...x,pr:nx}:x);STAFF=list;render();await db.doc('config/staff').set({list,updated:new Date().toISOString(),by:curUser})});
  const saveStaff=async list=>{STAFF=list;render();await db.doc('config/staff').set({list,updated:new Date().toISOString(),by:curUser})};
